import{describe,it,expect}from"vitest";import{readFileSync}from"node:fs";import{resolve,dirname}from"node:path";import{fileURLToPath}from"node:url";const __dirname=dirname(fileURLToPath(import.meta.url));describe("Lothal Ancient Port Explorer Tests",()=>{it("HTML contains historical overview, location, timeline, dockyard, and discoveries",()=>{const e=readFileSync(resolve(__dirname,"../../lothal-port-explorer/index.html"),"utf-8");expect(e).toContain('id="overview"'),expect(e).toContain('id="location-timeline"'),expect(e).toContain('id="dockyard-trade"'),expect(e).toContain('id="discoveries"'),expect(e).toContain('id="gallery"'),expect(e).toContain('id="references"'),expect(e).toContain("Lothal"),expect(e).toContain("Harappan"),expect(e).toContain("dockyard")}),it("CSS stylesheet exists and defines port styling tokens",()=>{const e=readFileSync(resolve(__dirname,"../../lothal-port-explorer/style.css"),"utf-8");expect(e).toContain("--port-gold"),expect(e).toContain(".port-main"),expect(e).toContain(".port-hero")}),it("JavaScript module initializes cleanly",()=>{const e=readFileSync(resolve(__dirname,"../../lothal-port-explorer/script.js"),"utf-8");expect(e).toContain("LothalPortExplorer"),expect(e).toContain("setupGalleryModal")})});